function drawDedenneAntennaMouse(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.3;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.5;

  const antLag = breathPhase - 0.45;
  const antWiggle = Math.sin(antLag) * 2.5;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 28 * (1.0 - 0.15 * breathSin), 7, 0, 0, Math.PI * 2); ctx.fill();

  // Đuôi đen uốn lượn & hoa sao
  ctx.strokeStyle = '#1e293b';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.arc(20, by + 28, 12, 0, Math.PI * 2);
  ctx.moveTo(8, by + 24); ctx.lineTo(-18, by + 32);
  ctx.stroke();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath();
  ctx.moveTo(-24, by + 30); ctx.lineTo(-34, by + 24); ctx.lineTo(-28, by + 36); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(-26, by + 32); ctx.lineTo(-34, by + 38); ctx.lineTo(-22, by + 38); ctx.fill();

  // Tai tròn
  ctx.beginPath(); ctx.arc(-20, by - 24, 11, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(20, by - 24, 11, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.arc(-20, by - 24, 8, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(20, by - 24, 8, 0, Math.PI * 2); ctx.fill();

  // Thân cam
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.ellipse(0, by + 12, 24 * sX, 22 * sY, 0, 0, Math.PI * 2); ctx.fill();
  // Bụng vàng kem
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.ellipse(0, by + 17, 16 * sX, 12 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Đầu cam
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.ellipse(0, by - 8, 20 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Râu ăng-ten
  ctx.strokeStyle = '#1e293b';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-16, by + 2); ctx.lineTo(-36, by - 6 + antWiggle);
  ctx.moveTo(-30, by - 8 + antWiggle); ctx.lineTo(-26, by - 2 + antWiggle);
  ctx.moveTo(-16, by + 6); ctx.lineTo(-34, by + 14 - antWiggle);
  ctx.moveTo(16, by + 2); ctx.lineTo(36, by - 6 - antWiggle);
  ctx.moveTo(30, by - 8 - antWiggle); ctx.lineTo(26, by - 2 - antWiggle);
  ctx.moveTo(16, by + 6); ctx.lineTo(34, by + 14 + antWiggle);
  ctx.stroke();

  // Má cam đậm
  ctx.fillStyle = '#ea580c';
  ctx.beginPath(); ctx.arc(-16, by + 4, 6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(16, by + 4, 6, 0, Math.PI * 2); ctx.fill();

  // Mắt đen
  if (!blink) {
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.ellipse(-9, by - 8, 4, 6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(9, by - 8, 4, 6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-10, by - 11, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(8, by - 11, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Miệng & răng
  ctx.fillStyle = '#881337';
  ctx.beginPath(); ctx.moveTo(0, by + 5); ctx.lineTo(-6, by); ctx.lineTo(6, by); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(-2, by, 4, 2);

  // Tay nhỏ
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.arc(-6, by + 16, 3, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(6, by + 16, 3, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
